// I. Basic File I/O System Calls

int fd;
char buf[1024];
ssize_t n;

// Open/Create (uses O_RDONLY, O_WRONLY, O_RDWR | O_CREAT)
fd = open("file.txt", O_RDWR | O_CREAT, 0644);
if (fd < 0) return; // Error handling (check errno)

// Read operation
n = read(fd, buf, 1023);

// Write operation
n = write(fd, "DATA", 4);

// Change file pointer offset
lseek(fd, 0, SEEK_SET);

close(fd);


// II. Exceptional Control Flow: Signal Handling (SIGCHLD Example)

void cleanup_child(int sig) {
    // Non-blocking wait to reap zombies
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

struct sigaction sa;
sa.sa_handler = cleanup_child;
sigemptyset(&sa.sa_mask);
sa.sa_flags = SA_RESTART; // Restart slow syscalls interrupted by signal

sigaction(SIGCHLD, &sa, NULL);


// III. Networking System Calls (TCP Listener Setup)

#define PORT 8080
int listenfd;
struct sockaddr_in serv_addr;
socklen_t addrlen;

// Create socket descriptor
listenfd = socket(AF_INET, SOCK_STREAM, 0);

// Assign local address/port (assumes serv_addr setup)
bind(listenfd, (SA *)&serv_addr, sizeof(serv_addr));

// Convert socket to a listening socket
listen(listenfd, 1024 /* backlog */);

// Wait for a client connection
int connfd = accept(listenfd, NULL, NULL);

close(listenfd);
